import{d as s,C as t,o as p,c as h,E as i,a3 as o}from"./chunks/framework.Q4yG9rk_.js";const x=JSON.parse('{"title":"井卦","description":"第四十八卦·水风井——木上有水，井。井不是「有水」这件事，而是「让水到达人手中」这件事：可汲是条件，供饮是落实，不封闭其养才是大成。","frontmatter":{"title":"井卦","description":"第四十八卦·水风井——木上有水，井。井不是「有水」这件事，而是「让水到达人手中」这件事：可汲是条件，供饮是落实，不封闭其养才是大成。","category":"hexagram","aliases":["井","水风井","井卦"],"source":["《周易》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/hexagrams/48-shuifengjing.md","filePath":"yijing/hexagrams/48-shuifengjing.md","lastUpdated":1792641266000}'),d={name:"yijing/hexagrams/48-shuifengjing.md"},q=s({...d,setup(u){const a=[{id:"jing",term:"井",pinyin:"jǐng",meaning:"水井。卦中既指具体的井，也指「供养之道」。",context:"全卦的关键不在「井里有水」，而在「水如何到达人手中」——彖传以「巽乎水而上水」释之。"},{id:"yi",term:"邑",pinyin:"yì",meaning:"聚落、城邑。",context:"「改邑不改井」：城邑可以迁改，井的所在与供养功能相对固定。"},{id:"jingjing",term:"往来井井",pinyin:"wǎng lái jǐng jǐng",meaning:"往来的人都到井边取水。",context:"写井的常养之性——人来人往，供养的需要始终存在。"},{id:"qi",term:"汔",pinyin:"qì",meaning:"几乎、将近。",context:"「汔至亦未繘井」：汲水几乎到井口了，却终究没有把水取上来——接近完成不等于完成。"},{id:"yu",term:"繘",pinyin:"jú",meaning:"汲水的绳索。此处训释各家有异。",context:"「未繘井」谓未完成汲取之功。彖传「未有功也」即释此句。"},{id:"lei",term:"羸",pinyin:"léi",meaning:"牵累、损伤。",context:"「羸其瓶」：汲水的瓶受损，以致汲水失败——已近成功，却因最后一环失手。"},{id:"qin",term:"禽",pinyin:"qín",meaning:"禽鸟。具体解释有差异，此从禽鸟。",context:"「旧井无禽」：废弃之井，连禽鸟也不来——重点在它已失去吸引取用者的作用。"},{id:"fu",term:"鲋",pinyin:"fù",meaning:"此处常释为井中的小鱼。",context:"「井谷射鲋」训释有差异，此取「水向下流注、只能润及井中小鱼」一路。"},{id:"weng",term:"瓮",pinyin:"wèng",meaning:"汲水的陶器。",context:"「瓮敝漏」：汲水的瓮已破损漏水——器具不能承载，水就到不了使用者手里。"},{id:"xie",term:"渫",pinyin:"xiè",meaning:"清除井中的淤泥。",context:"与「甃」分工不同：渫清淤（九三），甃护壁（六四）。"},{id:"ce",term:"恻",pinyin:"cè",meaning:"惋惜、恻然。",context:"「为我心恻」：井已淘清却无人饮用，因而惋惜。「我」如何理解，注家有讨论，不必直接认定是作者自述。"},{id:"zhou",term:"甃",pinyin:"zhòu",meaning:"用砖石砌护井壁。",context:"「井甃」：修护、稳固井体。小象「修井也」直接点明——修治本身有其正当性。"},{id:"lie",term:"洌",pinyin:"liè",meaning:"清洁、清澈。",context:"「井洌，寒泉食」：不只水清，而且可供饮用——九三「可用汲」却不「食」，到此才把清洁与供饮合起来。"},{id:"shou",term:"收",pinyin:"shōu",meaning:"汲取、汲水之功告成（训释有异，此从一说）。",context:"「井收勿幕」：供养之功已成。注意「收」不是「用完以后收起来」——那是不合本爻的解释。"},{id:"mu",term:"幕",pinyin:"mù",meaning:"覆盖、遮蔽；「勿幕」谓不要封闭、不阻断取用。",context:"「勿幕」重在供养不被遮蔽，不是「防止人掉下去」——后者既无经文依据，也不是合理的安全说明。"},{id:"gangzhong",term:"刚中",pinyin:"gāng zhōng",meaning:"阳爻而居中：九二、九五皆是。",context:"彖传「改邑不改井，乃以刚中也」——「刚中」是井卦稳定供养的结构依据：既有承担与支撑，又不失分寸。"},{id:"fushan",term:"无咎者，善补过也",pinyin:"wú jiù zhě",meaning:"《系辞》语：无咎不只「不好不坏」，而含善于修正、避免过失之意。",context:"但不能把一切「无咎」都读成「先出了错、再补救成功」——六四未明言先有事故，修井也可能是正常维护。"}],r=[{position:"初六",type:"yin",text:"井泥不食，旧井无禽。",xiang:"井泥不食，下也。旧井无禽，时舍也。",textModern:"井底淤泥积聚，水不能饮用；旧井废弃，连禽鸟也不来。初六居全卦最下，阴居阳位不得位，与六四同为阴爻而无正应。小象「下也」指出它处下近井底，「时舍也」则为时所弃、不再被使用。",xiangModern:"井中泥泞不能饮，是因为它处在最下；旧井无禽，是因为已被时势舍弃。"},{position:"九二",type:"yang",text:"井谷射鲋，瓮敝漏。",xiang:"井谷射鲋，无与也。",textModern:"水向下流注，只能润及井中小鱼；汲水的瓮又已破损漏水。九二阳居阴位不得位，但居下卦之中得中，与九五同为阳爻而无正应。小象「无与也」指出缺少相与、接引的条件——水并非全无，却没有形成正常的上汲供养。",xiangModern:"井水只能射及小鱼，是因为没有人来接引取用。"},{position:"九三",type:"yang",text:"井渫不食，为我心恻。可用汲，王明并受其福。",xiang:"井渫不食，行恻也。求王明，受福也。",textModern:"井已淘清淤泥却仍无人饮用，令人惋惜；它已经可以汲取了，只待明察的君王来取用，则上下同受其福。九三阳居阳位得位而不居中，与上六阴阳相应。小象「求王明」点出方向——寻求明察与取用，而不是把「不食」当成理所当然的终局。",xiangModern:"井已淘清却无人饮，令行人惋惜；求明察之人来取用，则共受其福。"},{position:"六四",type:"yin",text:"井甃，无咎。",xiang:"井甃无咎，修井也。",textModern:"用砖石砌护井壁，无咎。六四阴居阴位得位、不居中，与初六无正应，邻近九五。渫是清淤、甃是护壁，两者是不同的修治。小象直接说明「修井也」——在需要修治的时候承担修治，是合宜的行动。",xiangModern:"以砖石修砌井壁而无咎，因为这正是在修治水井。"},{position:"九五",type:"yang",text:"井洌，寒泉食。",xiang:"寒泉之食，中正也。",textModern:"井水清洁，清凉的泉水可供人饮用。九五阳居阳位得位，居上卦之中得中，兼具中与正，通常又称君位——所谓「其正」，应具体落实为「中正」，而非单纯位置高。这里不再是井泥或井渫而不食，而是清洁的水质与供饮作用结合起来了。",xiangModern:"清凉泉水得以供饮，是因为九五中正。"},{position:"上六",type:"yin",text:"井收勿幕，有孚元吉。",xiang:"元吉在上，大成也。",textModern:"汲水之功告成，却不覆盖、不封闭井口，让取用不被阻断；有诚信，大吉。上六阴居阴位得位，与九三阴阳相应，居于全卦之终——但「居终」不能机械理解为衰败，本爻明言「元吉」，应尊重具体经文。小象以「大成」概括。",xiangModern:"大吉在上爻，是因为供养之功大成。"}];return(m,n)=>{const e=t("DaoHexagramViewer"),l=t("DaoHexagramYaoCards"),g=t("DaoKeywordCards");return p(),h("div",null,[i(e,{name:"井",fullName:"水风井",upper:"☵",lower:"☴",guaCi:"井，改邑不改井，无丧无得，往来井井。汔至亦未繘井，羸其瓶，凶。",pinyin:["jǐng"],element:"木",direction:"东",insight:"井卦讲的不是「井里有水」，而是「水怎么到达人手中」：水质、井体、器具、取用，任一环出问题，供养都不成立。资源的存在不能代替供养的实现，接近完成也不能代替真正完成。",guaSlug:"48shuifengjing",lines:r}),n[0]||(n[0]=o("",11)),i(l,{element:"木",guaSlug:"48shuifengjing",glossary:a,items:r}),n[1]||(n[1]=o("",33)),i(g,{title:"字词释义",items:[{term:"井",pinyin:["jǐng"],meaning:"水井。卦中既指具体的井，也指「供养之道」——关键不在井里有水，而在水如何到达人手中。"},{term:"改邑不改井",pinyin:["gǎi","yì"],meaning:"城邑可以迁改，井的所在与供养功能相对固定。彖传以「刚中」释之：稳定供养的结构依据。"},{term:"无丧无得",pinyin:["wú","sàng"],meaning:"从井的常养之性看，不随人的往来而有简单的得失变化。但不是说井水物理上永不减少，也不是说具体水井无需维护。"},{term:"往来井井",pinyin:["wǎng","lái"],meaning:"往来的人都到井边取水。写井的常养之性——人来人往，供养的需要始终存在。"},{term:"汔至亦未繘井",pinyin:["qì","zhì"],meaning:"汲水几乎到井口了，却终究没有把水取上来。「繘」为汲水绳，训释各家有异。彖传「未有功也」即释此句。"},{term:"羸其瓶",pinyin:["léi","qí","píng"],meaning:"汲水的瓶受牵累、损伤，以致汲水失败——已近成功，却因最后一环失手，故凶。"},{term:"巽乎水而上水",pinyin:["xùn","hū"],meaning:"入于水中并把水汲取上来。彖传释井：不只看见水，也看见取得水的过程。"},{term:"井养而不穷",pinyin:["jǐng","yǎng"],meaning:"井的义理在于持续供养，而非一次性的占有或消耗。它是供养之道，不是对每一口具体水井状态的保证。"},{term:"劳民劝相",pinyin:["láo","mín"],meaning:"慰劳、勤恤民众，劝勉相助。不能读成「为了公共利益就可以无限度使民劳作」。"},{term:"井泥不食",pinyin:["jǐng","ní"],meaning:"井底淤泥积聚，水不能饮用。象曰「下也」——与其处下、近井底的状态有关。"},{term:"旧井无禽",pinyin:["jiù","jǐng"],meaning:"旧井废弃，连禽鸟也不来。象曰「时舍也」——为时所弃，不再被使用。重点在失去吸引取用者的作用。"},{term:"井谷射鲋",pinyin:["jǐng","gǔ"],meaning:"训释有差异，此取水向下流注、只能润及井中小鱼一路。象曰「无与也」——缺少相与、接引的条件。"},{term:"瓮敝漏",pinyin:["wèng","bì","lòu"],meaning:"汲水的瓮已破损漏水。水并非全无，却没有形成正常的上汲供养，器具又不能承载。"},{term:"渫",pinyin:["xiè"],meaning:"清除井中的淤泥。与「甃」分工不同：渫清淤（九三），甃护壁（六四）。"},{term:"为我心恻",pinyin:["wèi","wǒ"],meaning:"为此感到惋惜。「我」如何理解，可结合注家讨论，不必直接认定是作者自述。"},{term:"王明",pinyin:["wáng","míng"],meaning:"期望明察者识别、任用。象曰「求王明，受福也」——寻求明察与取用，而非把「不食」当作理所当然的终局。"},{term:"甃",pinyin:["zhòu"],meaning:"用砖石砌护井壁。象曰「修井也」——在需要修治的时候承担修治，是合宜的行动。"},{term:"井洌，寒泉食",pinyin:["liè","hán","quán"],meaning:"井水清洁，清凉的泉水可供人饮用。象曰「中正也」——九五「其正」应落实为「中正」，而非单纯位置高。"},{term:"井收勿幕",pinyin:["shōu","wù","mù"],meaning:"汲水之功告成，却不覆盖、不封闭井口，让取用不被阻断。「收」非「用完收起来」；「勿幕」非「防止人掉下去」。"},{term:"有孚",pinyin:["yǒu","fú"],meaning:"有诚信、可信实；结合井的情境，也可体会其供养具有可信赖性。不等于援引中孚卦的全部义理。"}]}),n[2]||(n[2]=o("",55))])}}});export{x as __pageData,q as default};
